(function(){var cfg=window.wxszbpc_config||{};if(document.cookie.indexOf('wxszbpc_visited=true')!==-1)return;var cookieMs=cfg.guideCookieMs||604800000;var now=new Date();now.setTime(now.getTime()+cookieMs);document.cookie='wxszbpc_visited=true;expires='+now.toUTCString()+';path=/';function wxszbpc_loadDriverResources(){return new Promise(function(resolve,reject){if(window.driver&&window.driver.js&&window.driver.js.driver){resolve();return;}var baseUrl=cfg.pluginUrl||'';var ver=cfg.pluginVer||'';var cssLink=document.createElement('link');cssLink.rel='stylesheet';cssLink.href=baseUrl+'assets/driver.min.css'+ver;var jsScript=document.createElement('script');jsScript.src=baseUrl+'assets/driver.min.js'+ver;var cssLoaded=false,jsLoaded=false;function checkAll(){if(cssLoaded&&jsLoaded)resolve();}cssLink.onload=function(){cssLoaded=true;checkAll();};cssLink.onerror=function(){reject(new Error('driver.css加载失败'));};jsScript.onload=function(){jsLoaded=true;checkAll();};jsScript.onerror=function(){reject(new Error('driver.js加载失败'));};document.head.appendChild(cssLink);document.head.appendChild(jsScript);});}function wxszbpc_findAiButton(){var mode=cfg.guideBtnMode||'';if(mode==='hijack'){var hijackSel=cfg.guideHijackSelector||'#ai-duihua';var hijackEl=document.querySelector('[href="'+hijackSel+'"]');var target=hijackEl?hijackEl.closest('.aitip'):document.querySelector('.aitip');if(target)return target;}else if(mode==='postchat'){var pcBtn=document.querySelector('#postChat_button');if(pcBtn)return pcBtn;}return document.querySelector('#postChat_button')||document.querySelector('.aitip')||null;}function wxszbpc_isElementReady(el){if(!el)return false;var rect=el.getBoundingClientRect();return rect.width>0&&rect.height>0;}function wxszbpc_runGuide(steps){if(steps.length===0)return;if(steps.length===1){var driverObj=window.driver.js.driver();driverObj.highlight({element:steps[0].element,popover:steps[0].popover});}else{var driverObj=window.driver.js.driver({showProgress:true,steps:steps});driverObj.drive();}}function wxszbpc_waitAndGuide(attempt){var MAX_ATTEMPTS=10;var INTERVAL=500;var isMobile=!!cfg.isMobile;var isHome=!!cfg.isHomePage;var searchTitle=cfg.guideSearchTitle||'小贴士';var searchDesc=cfg.guideSearchDesc||'在此处填写想搜索的内容，点击右侧AI搜索，结果更加精准哦';var aiTitle=cfg.guideAiTitle||'AI对话';var aiDesc=cfg.guideAiDesc||'点击此按钮，可与智能AI客服对话哦';var searchEl=document.querySelector('.line-form');var aiBtnEl=wxszbpc_findAiButton();var needAiBtn=!isMobile||cfg.guideMobileAiBtn;if(needAiBtn&&!aiBtnEl&&attempt<MAX_ATTEMPTS){setTimeout(function(){wxszbpc_waitAndGuide(attempt+1);},INTERVAL);return;}if(needAiBtn&&aiBtnEl&&!wxszbpc_isElementReady(aiBtnEl)&&attempt<MAX_ATTEMPTS){setTimeout(function(){wxszbpc_waitAndGuide(attempt+1);},INTERVAL);return;}var steps=[];if(isHome&&searchEl&&wxszbpc_isElementReady(searchEl)){if(!isMobile||cfg.guideMobileSearch){steps.push({element:searchEl,popover:{title:searchTitle,description:searchDesc,side:'left'}});}}if(aiBtnEl&&wxszbpc_isElementReady(aiBtnEl)){if(!isMobile||cfg.guideMobileAiBtn){steps.push({element:aiBtnEl,popover:{title:aiTitle,description:aiDesc,side:'left'}});}}wxszbpc_runGuide(steps);}function wxszbpc_initUserGuide(){wxszbpc_loadDriverResources().then(function(){setTimeout(function(){wxszbpc_waitAndGuide(0);},1500);}).catch(function(err){console.error('加载用户引导资源失败:',err);});}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',wxszbpc_initUserGuide);}else{wxszbpc_initUserGuide();}})();